INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (515,52,'Sanger测序法','第一代DNA测序技术，基于链终止或双脱氧法，产生约1kb的读长，用于人类基因组计划。','entity',1,25,0,0,'2026-07-17 14:45:02');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (516,52,'第二代测序','下一代测序技术，产生35-250bp短读长，包括Roche 454、Illumina和SOLiD平台，大幅提高通量。','entity',1,25,0,0,'2026-07-17 14:45:02');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (517,52,'第三代测序','单分子实时测序技术，如PacBio SMRT和Oxford Nanopore，无需扩增，产生长读长。','entity',1,25,0,0,'2026-07-17 14:45:02');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (518,52,'De Bruijn图','基于k-mer的图模型，将读段分解为重叠k-mer作为顶点，通过欧拉路径求解组装问题，适用于短读长。','entity',1,25,0,0,'2026-07-17 14:45:02');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (520,52,'从头预测','仅基于DNA序列内在信号（如剪接位点、起始密码子）预测基因，无需转录或蛋白证据。','entity',1,25,0,0,'2026-07-17 14:45:02');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (521,52,'广义隐马尔可夫模型','用于从头基因预测的统计模型，如GENSCAN和AUGUSTUS，模拟基因结构特征。','entity',1,25,0,0,'2026-07-17 14:45:02');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (522,52,'剪接比对','将cDNA或蛋白序列比对到基因组，识别内含子-外显子边界，支持证据导向的基因注释。','entity',1,25,0,0,'2026-07-17 14:45:02');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (523,52,'基因本体','标准化的功能注释体系，包括分子功能、细胞组分和生物学过程三个层面，用于描述基因产物功能。','entity',1,25,0,0,'2026-07-17 14:45:02');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (524,52,'KEGG通路','京都基因与基因组百科全书，提供代谢和信号通路的注释资源，用于功能分析。','entity',1,25,0,0,'2026-07-17 14:45:02');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (525,52,'比较基因组学','通过比较不同物种的基因组序列和基因家族，研究进化关系和功能保守性。','entity',1,25,0,0,'2026-07-17 14:45:02');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (526,52,'基因家族分析','识别和分类直系同源和旁系同源基因，研究基因复制和功能分化。','entity',1,25,0,0,'2026-07-17 14:45:02');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (527,52,'全基因组比对','对两个或多个基因组进行全局序列比对，用于识别保守区域和结构变异。','entity',1,25,0,0,'2026-07-17 14:45:02');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (528,52,'证据编码','GO注释中标记证据来源的代码，如EXP（实验推断）和IEA（电子注释），反映注释可靠性。','entity',1,25,0,0,'2026-07-17 14:45:02');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (529,52,'染色体级别基因组','通过Hi-C和光学图谱等技术将支架锚定到假染色体，实现接近完整染色体的组装水平。','entity',1,25,0,0,'2026-07-17 14:45:02');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (531,52,'基因组拼接','将测序读段组装成连续序列的过程，包括重叠群和支架的构建，是基因组分析的关键步骤。','entity',16,40,19,24,'2026-07-17 14:45:02');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (532,52,'基因组结构注释','在基因组序列中识别基因、非编码RNA、调控区域和重复元件等结构特征的过程。','entity',7,31,27,34,'2026-07-17 14:45:02');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (533,52,'基因功能富集分析','统计检验方法，评估一组基因在特定功能类别中是否显著富集，揭示生物学意义。','entity',2,26,47,55,'2026-07-17 14:45:02');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (537,52,'纳米孔测序','第三代测序技术，通过电泳驱动DNA单分子通过纳米孔，检测电流变化实现无标记测序。','entity',1,25,1684,1689,'2026-07-17 14:45:02');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (538,52,'Hi-C','捕获染色体构象的常用协议，通过测序分析染色质相互作用，辅助基因组组装和三维结构解析。','entity',5,29,2009,2013,'2026-07-17 14:45:02');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (539,52,'Scaffold','由重叠群通过配对读段连接而成的有序定向序列，用于构建更完整的基因组支架。','entity',2,26,4973,4981,'2026-07-17 14:45:02');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (541,52,'InterProScan','整合多种蛋白质特征识别方法的工具，用于预测蛋白质结构域和功能位点。','entity',4,28,13814,13826,'2026-07-17 14:45:02');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (542,52,'eggNOG','直系同源基因功能注释数据库，涵盖GO、KEGG、PFAM和CAZy等模块。','entity',2,26,13826,13832,'2026-07-17 14:45:02');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (543,52,'共线性分析','比较基因组中基因或序列的保守顺序，揭示染色体重排和进化事件。','entity',4,28,17183,17188,'2026-07-17 14:45:02');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (544,52,'MUMmer','基于最大唯一匹配的基因组比对工具，适用于大规模序列比较。','entity',1,25,18291,18297,'2026-07-17 14:45:02');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (545,53,'Chaos Game Representation (CGR)','一种将一维生物序列（如DNA、蛋白质）映射到二维空间的迭代函数系统算法，生成独特的混沌游戏分形模式。','entity',1,25,0,0,'2026-07-18 00:05:59');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (546,53,'Frequency Chaos Game Representation (FCGR)','CGR的离散化版本，通过预定义网格统计CGR点在各单元格中的频率，将序列转化为等尺寸的矩阵或图像。','entity',1,25,0,0,'2026-07-18 00:05:59');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (547,53,'Iterated Function System (IFS)','基于集合论的迭代函数系统，是CGR算法的数学基础，通过重复应用一组收缩映射生成分形。','entity',1,25,0,0,'2026-07-18 00:05:59');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (548,53,'Graphical bioinformatics','生物信息学分支，专注于将生物序列以图形方式表示，作为序列的数学不变量，用于可视化、比较和编码。','entity',1,25,0,0,'2026-07-18 00:05:59');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (549,53,'Scaling factor (sf)','CGR算法中控制点向顶点移动距离的比例参数，对于DNA通常为0.5，影响分形图案的紧凑性和重叠程度。','attribute',1,25,0,0,'2026-07-18 00:05:59');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (550,53,'Polyflake (Sierpinski n-gon)','为处理多于四个顶点（如20种氨基酸）而设计的CGR扩展，通过调整缩放因子（接吻数）避免点重叠。','entity',1,25,0,0,'2026-07-18 00:05:59');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (551,53,'Kissing number','在多边形CGR中用于计算缩放因子的参数，确保不同顶点对应的区域不重叠，适用于n-边形分形。','attribute',1,25,0,0,'2026-07-18 00:05:59');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (552,53,'Markov chain generalization','CGR被证明是广义马尔可夫链，其表示包含序列的完整状态信息，马尔可夫模型是CGR的特例。','relation',1,25,0,0,'2026-07-18 00:05:59');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (553,53,'Attractor','动力系统收敛到的点或区域，在CGR中对应序列的非随机分形模式，反映序列的内在结构。','entity',1,25,0,0,'2026-07-18 00:05:59');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (554,53,'Non-integer resolution','FCGR中网格划分不限于整数k-mer长度，允许非整数分辨率以处理基因组冗余和氨基酸编码。','attribute',1,25,0,0,'2026-07-18 00:05:59');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (555,53,'Weighted Pearson correlation coefficient (rw)','用于计算两个FCGR之间全局距离的加权皮尔逊相关系数，衡量序列相似性。','entity',1,25,0,0,'2026-07-18 00:05:59');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (556,53,'Global distance (d)','基于加权相关系数定义的FCGR间距离，值介于0到2之间，0表示序列高度相似。','attribute',1,25,0,0,'2026-07-18 00:05:59');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (557,53,'Phylogenetic analysis','利用CGR/FCGR的序列表示进行系统发育分析，通过比较分形模式推断物种进化关系。','entity',1,25,0,0,'2026-07-18 00:05:59');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (558,53,'Feature encoding for machine learning','将CGR/FCGR生成的图像或矩阵作为机器学习模型的输入特征，用于序列分类和预测。','entity',1,25,0,0,'2026-07-18 00:05:59');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (559,53,'DNA encoding','将DNA序列（A、C、G、T）映射到CGR正方形四个顶点，每个核苷酸对应特定坐标。','entity',1,25,0,0,'2026-07-18 00:05:59');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (561,53,'Vertex orientation','CGR中顶点（核苷酸或氨基酸）的排列方式，不同排列产生不同视觉模式，影响序列分析结果。','attribute',1,25,0,0,'2026-07-18 00:05:59');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (562,53,'Lossless representation','CGR的原始坐标表示可无损重建原始序列，从最后一个坐标点即可恢复完整序列信息。','attribute',1,25,0,0,'2026-07-18 00:05:59');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (563,53,'Lossy representation','FCGR作为粗粒度方法，通过网格化统计丢失了精确位置信息，属于有损压缩。','attribute',1,25,0,0,'2026-07-18 00:05:59');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (564,53,'Homology visualization','通过CGR/FCGR的灰度或彩色图像可视化不同基因组之间的同源性，模式相似性反映序列相似性。','entity',1,25,0,0,'2026-07-18 00:05:59');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (565,53,'White holes','FCGR图像中出现的空白区域，代表序列中缺失或低频的k-mer子序列。','entity',1,25,0,0,'2026-07-18 00:05:59');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (566,53,'Repetitive sequence identification','利用CGR模式识别基因组中的重复序列及其频率，重复序列在CGR中形成特定聚集模式。','entity',1,25,0,0,'2026-07-18 00:05:59');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (567,53,'Entropic profile','通过增加CGR分辨率并计算直方图熵生成的轮廓，用于区分随机序列与真实基因组序列。','entity',1,25,0,0,'2026-07-18 00:05:59');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (568,53,'Pseudorandom number generator testing','利用CGR可视化质量：高质量随机数生成器在CGR中不产生可见模式，用于检测随机性。','entity',1,25,0,0,'2026-07-18 00:05:59');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (569,53,'Purine-pyrimidine ordering','CGR顶点排列中嘌呤（A/G）和嘧啶（C/T）的对角或水平排列方式，影响序列模式的可视化。','attribute',1,25,0,0,'2026-07-18 00:05:59');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (570,53,'Dinucleotide frequency comparison','利用CGR/FCGR比较不同序列中二核苷酸（如CG、AT）的频率分布，用于基因功能分析。','entity',1,25,0,0,'2026-07-18 00:05:59');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (572,53,'Alignment-free sequence comparison','无需序列比对的比较方法，利用CGR/FCGR等表示直接比较序列的整体特征，用于系统发育分析。','entity',2,26,443,477,'2026-07-18 00:05:59');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (575,54,'Markov链模型 (MCM)','一种概率模型，通过概率表描述核苷酸或氨基酸的连续出现模式，是CGR模型的特殊情况。','entity',1,25,0,0,'2026-07-18 00:27:42');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (576,54,'隐马尔可夫模型 (HMM)','用于识别核苷酸连续模式中不同模式交替的统计模型，在功能基因组学中应用广泛。','entity',1,25,0,0,'2026-07-18 00:27:42');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (577,54,'基因组序列','生物体完整的DNA序列，包含编码和非编码区域，是CGR分析的主要对象。','entity',1,25,0,0,'2026-07-18 00:27:42');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (578,54,'核苷酸','DNA的基本组成单位，包括腺嘌呤(A)、胞嘧啶(C)、鸟嘌呤(G)和胸腺嘧啶(T)。','entity',1,25,0,0,'2026-07-18 00:27:42');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (579,54,'寡核苷酸','短链核苷酸序列，通常用于作为标记来比对更大的序列。','entity',1,25,0,0,'2026-07-18 00:27:42');
