INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (581,54,'thrA基因','大肠杆菌K-12中编码高丝氨酸脱氢酶的基因，位于苏氨酸操纵子中。','entity',1,25,0,0,'2026-07-18 00:27:42');
