INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (583,54,'thrC基因','大肠杆菌K-12中编码苏氨酸合酶的基因，位于苏氨酸操纵子中。','entity',1,25,0,0,'2026-07-18 00:27:42');
