INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (585,54,'迭代映射','一种数学过程，通过反复应用一个函数来生成序列，CGR的核心算法。','entity',1,25,0,0,'2026-07-18 00:27:42');
