INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (590,54,'全局距离','基于加权皮尔逊相关系数定义的DNA序列间距离，值在0到2之间。','entity',1,25,0,0,'2026-07-18 00:27:42');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (591,54,'局部同源性','基因组序列中局部区域的相似性，CGR通过坐标距离来识别。','entity',1,25,0,0,'2026-07-18 00:27:42');
