INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (597,54,'进化辐射','物种或基因在进化过程中快速分化产生多种新形式的现象，文中用于解释thrB的差异。','entity',1,25,0,0,'2026-07-18 00:27:42');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (599,54,'sequence','关键词：sequence (频率:39, 得分:0.016)','entity',39,50,67,75,'2026-07-18 00:27:42');
