INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (601,54,'The','关键词：The (频率:75, 得分:0.014)','entity',75,50,1132,1135,'2026-07-18 00:27:42');
