INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (604,56,'细胞谱系 (Cell Lineage)','描述多细胞生物中细胞从祖先到后代的发育与分化历史，反映细胞间的进化关系。','entity',1,25,0,0,'2026-07-18 02:17:09');
