INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (609,56,'局部搜索 (Local Search)','通过迭代调整树结构以优化目标函数（如似然）的启发式优化算法。','entity',1,25,0,0,'2026-07-18 02:17:09');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (610,56,'细胞谱系树推断 (Cell Lineage Tree Inference)','利用单细胞数据重建细胞间进化关系树的计算过程。','entity',1,25,0,0,'2026-07-18 02:17:09');
