INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (613,56,'大规模单细胞数据 (Large Single-cell Data)','包含数万甚至更多细胞的高通量单细胞测序数据集。','entity',1,25,0,0,'2026-07-18 02:17:09');
