INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (615,56,'进化历史 (Evolutionary History)','细胞在发育或疾病过程中发生的突变积累与分裂事件的时序关系。','entity',1,25,0,0,'2026-07-18 02:17:09');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (616,56,'发育 (Development)','多细胞生物从受精卵到成体的细胞分化与组织形成过程。','entity',1,25,0,0,'2026-07-18 02:17:09');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (617,56,'衰老 (Aging)','生物体随时间发生的功能衰退，与细胞谱系中突变积累相关。','entity',1,25,0,0,'2026-07-18 02:17:09');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (618,56,'癌症 (Cancer)','由体细胞突变积累导致的恶性增殖疾病，其克隆进化可通过谱系树研究。','entity',1,25,0,0,'2026-07-18 02:17:09');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (619,56,'系统发育树 (Phylogenetic Tree)','表示物种或细胞间进化关系的分支图，细胞谱系树是其特例。','entity',1,25,0,0,'2026-07-18 02:17:09');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (620,56,'计算挑战 (Computational Challenge)','处理大规模、稀疏、噪声单细胞数据时面临的时间与内存复杂度问题。','attribute',1,25,0,0,'2026-07-18 02:17:09');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (621,56,'最优树 (Optimal Tree)','在给定模型下具有最高似然或最低代价的细胞谱系树。','entity',1,25,0,0,'2026-07-18 02:17:09');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (622,56,'模拟数据 (Simulated Data)','通过计算机生成、已知真实谱系树的测试数据，用于评估方法准确性。','entity',1,25,0,0,'2026-07-18 02:17:09');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (623,56,'真实生物学数据 (Real Biological Data)','从实际生物样本（如肿瘤组织）中测序获得的单细胞数据。','entity',1,25,0,0,'2026-07-18 02:17:09');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (624,56,'准确性 (Accuracy)','推断的细胞谱系树与真实树之间的一致程度，常用拓扑距离等指标衡量。','attribute',1,25,0,0,'2026-07-18 02:17:09');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (625,56,'效率 (Efficiency)','算法运行所需的时间与内存资源，ScisTree2在此方面优于现有方法。','attribute',1,25,0,0,'2026-07-18 02:17:09');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (626,56,'突变 (Mutation)','DNA序列中发生的永久性改变，是细胞谱系树构建的基础标记。','entity',1,25,0,0,'2026-07-18 02:17:09');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (627,56,'等位基因丢失 (Allele Dropout)','单细胞测序中一个等位基因未被扩增或检测到的现象，增加数据噪声。','entity',1,25,0,0,'2026-07-18 02:17:09');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (628,56,'假阳性突变 (False Positive Mutation)','测序或分析错误导致的虚假突变信号，影响谱系推断准确性。','entity',1,25,0,0,'2026-07-18 02:17:09');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (629,56,'似然函数 (Likelihood Function)','在给定模型和树结构下观察到当前数据的概率，用于评估树的质量。','entity',1,25,0,0,'2026-07-18 02:17:09');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (630,56,'启发式搜索 (Heuristic Search)','通过近似策略（如局部搜索）在巨大解空间中寻找高质量树的方法。','entity',1,25,0,0,'2026-07-18 02:17:09');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (631,56,'细胞异质性 (Cellular Heterogeneity)','同一组织或肿瘤中不同细胞在基因型、表型上的差异，单细胞测序可揭示。','entity',1,25,0,0,'2026-07-18 02:17:09');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (632,56,'克隆进化 (Clonal Evolution)','癌细胞群体通过突变和选择产生亚克隆的达尔文式进化过程。','entity',1,25,0,0,'2026-07-18 02:17:09');
INSERT INTO `knowledge_concepts` (`id`, `knowledge_document_id`, `concept_name`, `description`, `concept_type`, `frequency`, `size`, `position_start`, `position_end`, `created_at`) VALUES (633,56,'cell','关键词：cell (频率:11, 得分:0.084)','entity',11,35,10,14,'2026-07-18 02:17:09');
